  {
    json: {
      goal: goal.trim(),
      priority,
      requestedBy,
      scope: body.scope || {},
      receivedAt: new Date().toISOString()
    }
  }
];

const requestId = `PROC-${Date.now()}-${Math.random()
  .toString(36)
  .substring(2, 8)
  .toUpperCase()}`;

return [
  {
    json: {
      ...$json,
      requestId
    }
  }
];

