const input = $input.first().json;

// Get the AI response from different possible OpenAI output structures
let raw =
  input.output?.[0]?.content?.[0]?.text ??
  input.output_text ??
  input.text ??
  input.output ??
  '';

// If the AI already returned an object, use it directly
if (typeof raw === 'object' && raw !== null) {
  return [
    {
      json: raw
    }
  ];
}

// Convert response to string
raw = String(raw).trim();

// Remove Markdown JSON code fences if AI added them
const cleaned = raw
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let result;

try {
  result = JSON.parse(cleaned);
} catch (error) {
  throw new Error(
    `AI Evaluation Result is not valid JSON.\nRaw response: ${cleaned.substring(0, 1000)}`
  );
}

// const result = $json;

return [
  {
    json: {
      requestId: result.requestId,
      goal: result.goal,
      objective: result.objective,
      domain: result.procurement_domain,
      priority: result.priority,
      requiredData: result.required_data_sources || [],
      candidateWorkflows: result.candidate_sub_workflows || [],
