function extractJson(text) {
  if (!text) {
    throw new Error('AI response is empty');
  }

  text = text.trim();

  // Remove markdown code fences
  text = text.replace(/^```json\s*/i, '');
  text = text.replace(/^```\s*/i, '');
  text = text.replace(/\s*```$/i, '');

  return JSON.parse(text);
}

