const item = $input.first()?.json || {};
const text = item.message?.text || item.text || "";

// Helper regex extractor
const extractField = (label, textString) => {
  const regex = new RegExp(`${label}:\\s*([^\\n_]+)`, 'i');
  const match = textString.match(regex);
  return match ? match[1].trim() : null;
};

// 1. Extract values from text payload
const supplierName = extractField('Supplier', text);
const supplierId = extractField('Supplier ID', text);
const riskLevel = extractField('Risk Level', text);
const riskScoreStr = extractField('Risk Score', text);
const recommendedAction = extractField('Recommended Action', text);
const reason = extractField('Reason', text);
const approvalRequestId = extractField('Approval Request', text);

// 2. Extract or determine Approval Decision
const rawDecision = 
  item.approvalDecision || 
  item.decision || 
  item.action || 
  item.body?.approvalDecision || 
  item.body?.decision || 
  item.query?.decision || 
  item.query?.approved ||
  (item.ok ? 'APPROVED' : 'REJECTED'); // Default fallback for successful Slack wait node step

let decision = String(rawDecision).trim().toUpperCase();
if (['APPROVE', 'YES', 'TRUE'].includes(decision)) decision = 'APPROVED';
if (['REJECT', 'NO', 'FALSE'].includes(decision)) decision = 'REJECTED';

// 3. Return fully parsed workflow object
return {
  json: {
    approvalDecision: decision,
    isApproved: decision === 'APPROVED',
    supplierId: supplierId || item.supplierId || null,
    supplierName: supplierName || item.supplierName || null,
    riskLevel: riskLevel || item.riskLevel || null,
    riskScore: riskScoreStr ? parseInt(riskScoreStr, 10) : (item.riskScore || 0),
    recommendedAction: recommendedAction || item.recommendedAction || null,
    reason: reason || item.reason || null,
    approvalRequestId: approvalRequestId || item.approvalRequestId || null,
    slackChannel: item.channel,
    slackTimestamp: item.message_timestamp || item.message?.ts
  }
};

