const items = $input.all();
const output = [];

for (const item of items) {
  const json = item.json;
  const rawAction = String(json.recommendedAction || json.action || json.approvalDecision || '');

  // Split combined decisions by delimiter (AND, comma, or underscore combinations)
  const actionsList = rawAction.split(/\s*AND\s*|,\s*/i);

  for (const actionItem of actionsList) {
    if (actionItem.trim()) {
      output.push({
        json: {
          ...json,
          singleAction: actionItem.trim().toUpperCase()
        }
      });
    }
  }
